#!/usr/bin/env python3
"""quality_gate.py — 小程序反编译产物质量门禁。

输入一个还原后的源码目录，输出可机器判定的质量分与状态：
  ok      >=70 分：结构与内容基本完整，可作为主审计产物
  partial 35-69：可用但存在缺口（如新模板、分包占位、WXML 绑定丢失）
  failed  <35  ：不可用（缺 app.json/pages、几乎无内容）

用法：python3 quality_gate.py --dir <source_dir> [--json-out <file>]
退出码：0 = ok/partial；1 = failed。
"""
import argparse
import json
import os
import re
import sys

CONFIG_NAMES = ("app.json", "app-config.json")
PLACEHOLDER_PATTERNS = (
    "Generated by @unveilr",
    "generated by unveilr",
    "<!-- placeholder -->",
)
JS_PLACEHOLDER_RE = re.compile(r"Page\s*\(\s*\{\s*data\s*:\s*\{\s*\}\s*\}\s*\)")
TEMPLATE_MARKERS = ("batchAddCompiledTemplate", "__wxCodeSpace__", "setRuntimeGlobals")


def walk_files(root):
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in (".git", "node_modules")]
        for fn in filenames:
            yield os.path.join(dirpath, fn)


def find_config(root):
    found = []
    for p in walk_files(root):
        if os.path.basename(p) in CONFIG_NAMES:
            found.append(p)
    if not found:
        return None
    # 优先 app.json，其次浅层路径
    found.sort(key=lambda p: (os.path.basename(p) != "app.json", p.count(os.sep), p))
    return found[0]


def load_config(path):
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            return json.load(f), None
    except Exception as e:  # noqa: BLE001
        return None, str(e)


def count_routes(cfg):
    pages = cfg.get("pages") or []
    sub = cfg.get("subPackages") or cfg.get("subpackages") or []
    sub_pages = 0
    for item in sub:
        if isinstance(item, dict):
            sub_pages += len(item.get("pages") or [])
    return len(pages), sub_pages


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--dir", required=True)
    ap.add_argument("--json-out", default="")
    args = ap.parse_args()
    root = os.path.abspath(args.dir)
    if not os.path.isdir(root):
        print(json.dumps({"ok": False, "status": "failed", "error": "目录不存在"}, ensure_ascii=False))
        sys.exit(1)

    cfg_path = find_config(root)
    cfg = None
    cfg_err = "未找到 app.json/app-config.json"
    if cfg_path:
        cfg, cfg_err = load_config(cfg_path)

    metrics = {
        "config_path": cfg_path or "",
        "config_ok": bool(cfg),
        "pages": 0,
        "subpackage_pages": 0,
        "wxml_total": 0,
        "wxml_nonempty": 0,
        "wxml_with_bindings": 0,
        "wxml_placeholder": 0,
        "js_total": 0,
        "js_nonempty": 0,
        "js_placeholder": 0,
        "js_bytes": 0,
        "partial_template": False,
    }
    warnings = []
    if cfg:
        metrics["pages"], metrics["subpackage_pages"] = count_routes(cfg)
    else:
        warnings.append("配置解析失败: %s" % cfg_err)

    wxml_total = wxml_nonempty = wxml_bind = wxml_ph = 0
    js_total = js_nonempty = js_ph = js_bytes = 0
    template_hit = False

    for p in walk_files(root):
        ext = os.path.splitext(p)[1].lower()
        try:
            size = os.path.getsize(p)
        except OSError:
            continue
        if ext == ".wxml":
            wxml_total += 1
            if size <= 0:
                continue
            try:
                text = open(p, "r", encoding="utf-8", errors="replace").read()
            except OSError:
                continue
            if text.strip():
                wxml_nonempty += 1
            if "{{" in text:
                wxml_bind += 1
            if any(m in text for m in PLACEHOLDER_PATTERNS):
                wxml_ph += 1
        elif ext in (".js", ".wxs"):
            js_total += 1
            js_bytes += size
            if size <= 0:
                continue
            try:
                text = open(p, "r", encoding="utf-8", errors="replace").read()
            except OSError:
                continue
            if text.strip():
                js_nonempty += 1
            if JS_PLACEHOLDER_RE.search(text):
                js_ph += 1
            if any(m in text for m in TEMPLATE_MARKERS):
                template_hit = True

    metrics.update({
        "wxml_total": wxml_total,
        "wxml_nonempty": wxml_nonempty,
        "wxml_with_bindings": wxml_bind,
        "wxml_placeholder": wxml_ph,
        "js_total": js_total,
        "js_nonempty": js_nonempty,
        "js_placeholder": js_ph,
        "js_bytes": js_bytes,
        "partial_template": template_hit,
    })

    score = 0.0
    if metrics["config_ok"]:
        score += 30
    if metrics["pages"] > 0:
        score += 20
    if wxml_total:
        score += 25 * (wxml_nonempty / wxml_total)
        score += 15 * (wxml_bind / wxml_total)
    if js_total:
        score += 10 * (js_nonempty / js_total)
    if template_hit:
        score -= 20
        warnings.append("检测到 __wxCodeSpace__/batchAddCompiledTemplate 新模板，WXML 可能不完整")
    if wxml_total and wxml_bind == 0:
        score -= 10
        warnings.append("WXML 全部没有 {{}} 绑定，可能还原丢失（优先 wedecode/unveilr）")
    if wxml_ph:
        warnings.append("WXML 存在反编译占位文件 %d 个" % wxml_ph)
    if js_ph and js_total:
        ratio = js_ph / js_total
        if ratio > 0.3:
            warnings.append("JS 占位页比例较高（%.0f%%），分包代码可能未下载" % (ratio * 100))
    if not metrics["config_ok"]:
        warnings.append("缺少可解析的 app.json/app-config.json")
    if metrics["pages"] == 0:
        warnings.append("pages 为空")
    if wxml_total == 0:
        warnings.append("没有任何 WXML 文件（可能只做了原始提取）")

    score = max(0.0, min(100.0, round(score, 1)))
    status = "ok" if score >= 70 else ("partial" if score >= 35 else "failed")
    result = {
        "ok": status != "failed",
        "status": status,
        "score": score,
        "metrics": metrics,
        "warnings": warnings,
    }
    if args.json_out:
        os.makedirs(os.path.dirname(os.path.abspath(args.json_out)), exist_ok=True)
        with open(args.json_out, "w", encoding="utf-8") as f:
            json.dump(result, f, ensure_ascii=False, indent=2)
    print(json.dumps(result, ensure_ascii=False))
    sys.exit(0 if status != "failed" else 1)


if __name__ == "__main__":
    main()
